create table if not exists balance_snapshots(id bigserial primary key, establishment_name text not null, snapshot_date date not null, source_filename text not null, sheet_name text, row_count integer not null default 0, created_at timestamptz not null default now());
create table if not exists balance_lines(id bigserial primary key,snapshot_id bigint not null references balance_snapshots(id) on delete cascade,line_no integer,account text not null,label text,debit numeric(16,2) not null default 0,credit numeric(16,2) not null default 0,net numeric(16,2) not null default 0);
create index if not exists idx_balance_lines_snapshot_account on balance_lines(snapshot_id,account);
create table if not exists accounting_alerts(id bigserial primary key,snapshot_id bigint not null references balance_snapshots(id) on delete cascade,rule_code text not null,severity text not null,title text not null,detail text not null,account text,amount numeric(16,2),created_at timestamptz not null default now());
